function diffPixels(a,b,w,h,opts){
  opts=opts||{};
  var th=(typeof opts.threshold==='number')?opts.threshold:0;
  if(!a||!b) return {error:'缺少像素数据'};
  if(a.length!==b.length) return {error:'像素数据长度不一致（宽度或高度不同）'};
  if(!(w>0&&h>0&&w*h*4<=a.length)) return {error:'宽高与像素数据不匹配'};
  var total=w*h, diffCount=0, maxDelta=0, sumDelta=0;
  var minX=1e9,minY=1e9,maxX=-1,maxY=-1;
  var rowCounts=new Array(h); for(var y=0;y<h;y++) rowCounts[y]=0;
  var mask=new Array(total);
  for(var i=0;i<total;i++){
    var o=i*4, d=0;
    for(var c=0;c<3;c++){
      var dd=Math.abs((a[o+c]||0)-(b[o+c]||0));
      if(dd>d)d=dd;
    }
    if(d>th){
      diffCount++; sumDelta+=d;
      if(d>maxDelta)maxDelta=d;
      var x=i%w, y2=(i-x)/w;
      if(x<minX)minX=x; if(x>maxX)maxX=x;
      if(y2<minY)minY=y2; if(y2>maxY)maxY=y2;
      rowCounts[y2]++; mask[i]=1;
    } else { mask[i]=0; }
  }
  var ratio= total? diffCount/total : 0;
  return {total:total, diffCount:diffCount, ratio:ratio, ratioPct:Math.round(ratio*10000)/100,
          maxDelta:maxDelta, avgDelta:diffCount? Math.round(sumDelta/diffCount*100)/100:0,
          bbox:diffCount?{minX:minX,minY:minY,maxX:maxX,maxY:maxY}:null,
          rowCounts:rowCounts, mask:mask, identical:diffCount===0};
}
function classifyDiff(r){
  if(!r||r.identical) return {level:'identical', label:'完全一致'};
  if(r.ratioPct<1) return {level:'minor', label:'微小差异'};
  if(r.ratioPct<10) return {level:'visible', label:'可见差异'};
  return {level:'major', label:'显著差异'};
}
var EXPORTS={diffPixels:diffPixels, classifyDiff:classifyDiff};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ImageDiffForgePure = EXPORTS; }
